"""Build curated CS journals (~180) + conferences (~180)."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data/private/venues.json"

HINT_J = {1: "~35%+", 2: "~20–35%", 3: "~12–20%", 4: "~6–12%", 5: "<6% / invite-heavy"}
HINT_C = {1: "~35%+", 2: "~22–35%", 3: "~15–22%", 4: "~8–15%", 5: "<10% flagship"}


def venue(kind, name, abbr, publisher, impact, rigor, domains, keywords, specialty, url, issn=""):
    return {
        "id": f"{'j' if kind == 'journal' else 'c'}-{abbr.lower().replace(' ', '-').replace('&', 'and').replace('/', '-')}",
        "kind": kind,
        "name": name,
        "abbr": abbr,
        "publisher": publisher,
        "impactFactor": float(impact),
        "rigor": int(rigor),
        "acceptanceHint": (HINT_J if kind == "journal" else HINT_C).get(int(rigor), "n/a"),
        "domains": domains,
        "keywords": keywords,
        "specialty": specialty,
        "url": url,
        "issn": issn,
        "notes": "",
    }


