    journals = [venue("journal", *row) for row in journals_raw]
    conferences = [venue("conference", *row) for row in conferences_raw]

    # dedupe by abbr
    def dedupe(items):
        seen = set()
        out = []
        for v in items:
            if v["abbr"] in seen:
                continue
            seen.add(v["abbr"])
            out.append(v)
        return out

    journals = dedupe(journals)
    conferences = dedupe(conferences)
    all_v = journals + conferences
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(all_v, ensure_ascii=False, indent=2), encoding="utf-8")
    print("journals", len(journals), "conferences", len(conferences), "total", len(all_v))


